#!/usr/bin/env bash
set -euo pipefail

# ── build-ios.sh ────────────────────────────────────────────────────
# Reliable iOS build script for merge skill agents.
# Auto-detects scheme/project, handles timeout, preserves exit codes,
# and outputs structured results the agent can parse.
#
# Exit codes:
#   0 = build succeeded
#   1 = build failed (compile errors)
#   2 = timed out
#   3 = setup error (no project found, no scheme, etc.)
#
# Usage:
#   ./build-ios.sh --project-dir /path/to/project [--scheme MyApp] [--timeout 120] [--destination 'iPhone 17 Pro']
# ────────────────────────────────────────────────────────────────────

PROJECT_DIR=""
SCHEME=""
TIMEOUT=120
DESTINATION=""
LOG_FILE=""

# ── Parse args ─────────────────────────────────────────────────────
while [[ $# -gt 0 ]]; do
  case "$1" in
    --project-dir)  PROJECT_DIR="$2"; shift 2 ;;
    --scheme)       SCHEME="$2"; shift 2 ;;
    --timeout)      TIMEOUT="$2"; shift 2 ;;
    --destination)  DESTINATION="$2"; shift 2 ;;
    *) echo "BUILD_STATUS:ERROR"; echo "Unknown arg: $1"; exit 3 ;;
  esac
done

if [[ -z "$PROJECT_DIR" ]]; then
  echo "BUILD_STATUS:ERROR"
  echo "Missing --project-dir"
  exit 3
fi

cd "$PROJECT_DIR"

# ── Auto-detect .xcworkspace or .xcodeproj ───────────────────────
WORKSPACE=$(find . -maxdepth 1 -name "*.xcworkspace" -type d | head -1)
XCODEPROJ=$(find . -maxdepth 1 -name "*.xcodeproj" -type d | head -1)

TARGET_FILE=""
TARGET_FLAG=""

if [[ -n "$WORKSPACE" ]]; then
  TARGET_FILE="$PROJECT_DIR/$(basename "$WORKSPACE")"
  TARGET_FLAG="-workspace"
elif [[ -n "$XCODEPROJ" ]]; then
  TARGET_FILE="$PROJECT_DIR/$(basename "$XCODEPROJ")"
  TARGET_FLAG="-project"
else
  echo "BUILD_STATUS:ERROR"
  echo "No .xcworkspace or .xcodeproj found in $PROJECT_DIR"
  exit 3
fi

# ── Auto-detect scheme if not provided ─────────────────────────────
if [[ -z "$SCHEME" ]]; then
  # Use awk instead of sed+grep pipeline to avoid pipefail issues.
  # Handles output that ends without a trailing blank line after Schemes.
  SCHEME=$(xcodebuild "$TARGET_FLAG" "$TARGET_FILE" -list 2>/dev/null \
    | awk '/Schemes:/{found=1; next} found && NF{gsub(/^[ \t]+/,""); print; exit}') || true
  if [[ -z "$SCHEME" ]]; then
    echo "BUILD_STATUS:ERROR"
    echo "Could not auto-detect scheme from $TARGET_FILE"
    echo "Hint: pass --scheme explicitly, e.g. --scheme $(basename "$TARGET_FILE" | sed 's/\.xcworkspace//;s/\.xcodeproj//')"
    exit 3
  fi
fi

# ── Auto-detect destination if not provided ────────────────────────
if [[ -z "$DESTINATION" ]]; then
  DESTINATION=$(xcrun simctl list devices available -j 2>/dev/null \
    | python3 -c "
import json, sys
data = json.load(sys.stdin)
for runtime, devices in sorted(data['devices'].items(), reverse=True):
    for d in devices:
        if d['isAvailable'] and 'iPhone' in d['name']:
            print(d['name']); sys.exit(0)
sys.exit(1)
" 2>/dev/null) || true
  if [[ -z "$DESTINATION" ]]; then
    echo "BUILD_STATUS:ERROR"
    echo "No available iPhone simulator found"
    exit 3
  fi
fi

# ── Setup log file ─────────────────────────────────────────────────
LOG_DIR="$PROJECT_DIR/.locofy/agent/build-logs"
mkdir -p "$LOG_DIR"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
LOG_FILE="$LOG_DIR/build_${TIMESTAMP}.log"
ERROR_FILE="$LOG_DIR/errors_${TIMESTAMP}.txt"

# ── Helper: echo to both stdout and log file ─────────────────────
out() {
  echo "$@" | tee -a "$LOG_FILE"
}

# ── Print config ───────────────────────────────────────────────────
out "BUILD_CONFIG:project=$TARGET_FILE"
out "BUILD_CONFIG:scheme=$SCHEME"
out "BUILD_CONFIG:destination=$DESTINATION"
out "BUILD_CONFIG:timeout=${TIMEOUT}s"
out "BUILD_CONFIG:log=$LOG_FILE"
out "---"

# ── Build with timeout ─────────────────────────────────────────────
BUILD_EXIT=0

# Use gtimeout (from coreutils) if available, fall back to perl-based timeout
timeout_cmd() {
  local secs=$1; shift
  if command -v gtimeout &>/dev/null; then
    gtimeout "$secs" "$@"
  else
    # perl-based timeout for macOS (no coreutils)
    perl -e '
      alarm shift @ARGV;
      $SIG{ALRM} = sub { kill "TERM", $pid; exit 142 };
      $pid = fork();
      if ($pid == 0) { exec @ARGV; die "exec: $!" }
      waitpid($pid, 0);
      exit ($? >> 8);
    ' "$secs" "$@"
  fi
}

timeout_cmd "$TIMEOUT" \
  xcodebuild \
    "$TARGET_FLAG" "$TARGET_FILE" \
    -scheme "$SCHEME" \
    -destination "platform=iOS Simulator,name=$DESTINATION" \
    -configuration Debug \
    build \
  >> "$LOG_FILE" 2>&1 || BUILD_EXIT=$?

# ── Interpret result ───────────────────────────────────────────────
out "---"

# timeout returns 124 (gtimeout) or 142 (perl alarm)
if [[ $BUILD_EXIT -eq 124 || $BUILD_EXIT -eq 142 ]]; then
  out "BUILD_STATUS:TIMEOUT"
  out "Build timed out after ${TIMEOUT}s. Log: $LOG_FILE"
  exit 2
elif [[ $BUILD_EXIT -ne 0 ]]; then
  out "BUILD_STATUS:FAILED"
  out ""
  # Extract ALL error lines into a dedicated error file
  grep -E ':\d+:\d+: (error|fatal error):' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
  if [[ ! -s "$ERROR_FILE" ]]; then
    # Fallback for linker/undefined symbol errors
    grep -E '(linker error|undefined symbol|Undefined symbols)' "$LOG_FILE" 2>/dev/null > "$ERROR_FILE" || true
  fi
  if [[ -s "$ERROR_FILE" ]]; then
    ERROR_COUNT=$(wc -l < "$ERROR_FILE" | tr -d ' ')
    out "ERRORS_FILE:$ERROR_FILE"
    out "ERROR_COUNT:$ERROR_COUNT"
    # Also print first 20 to stdout for quick visibility
    head -20 "$ERROR_FILE" | tee -a "$LOG_FILE"
    if [[ "$ERROR_COUNT" -gt 20 ]]; then
      out "... and $((ERROR_COUNT - 20)) more errors in $ERROR_FILE"
    fi
  else
    rm -f "$ERROR_FILE"
    out "Build failed (no structured errors found). See log: $LOG_FILE"
  fi
  exit 1
else
  out "BUILD_STATUS:SUCCESS"
  out "Build succeeded"
  # Show warnings if any
  WARN_LINES=$(grep -c 'warning:' "$LOG_FILE" 2>/dev/null | tr -d '[:space:]' || echo "0")
  if [[ "$WARN_LINES" =~ ^[0-9]+$ ]] && [[ "$WARN_LINES" -gt 0 ]]; then
    out "($WARN_LINES warnings — see $LOG_FILE)"
  fi
  exit 0
fi
